/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *   - Non-ERROR logs (including blank Level__c) are deleted once they are
 *     older than 30 days.
 *   - ERROR logs are kept longer and deleted only once they are older
 *     than 180 days.
 *
 * The deletion is performed synchronously inside execute() so it completes
 * within a single transaction (and works correctly when the scheduled job
 * runs during Test.stopTest).
 */
public with sharing class LogPurgeJob implements Schedulable {

    // No-argument constructor (required for scheduling).
    public LogPurgeJob() {}

    /**
     * Schedulable entry point. Deletes the eligible log records.
     */
    public void execute(SchedulableContext sc) {
        Datetime thirtyDaysAgo  = Datetime.now().addDays(-30);
        Datetime oneEightyAgo   = Datetime.now().addDays(-180);

        // Non-ERROR logs (including blank Level__c, since "!= 'ERROR'" in
        // SOQL also matches null) are purged after 30 days; ERROR logs are
        // kept until they are older than 180 days.
        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :thirtyDaysAgo
            AND (Level__c != 'ERROR' OR CreatedDate < :oneEightyAgo)
        ];

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    /**
     * Schedules this job to run every night at 02:00.
     *
     * @return the Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Seconds Minutes Hours Day-of-month Month Day-of-week
        String cron = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cron, new LogPurgeJob());
    }
}
