@IsTest
private class InvoicingServiceTest {
    // Shared flag used to prove authenticate() runs before any createInvoice().
    private static Boolean authenticated = false;

    // ---------------------------------------------------------------------
    // Answers used to pin down call ordering functionally.
    // ---------------------------------------------------------------------

    private class AuthAnswer implements fflib_Answer {
        public Object answer(fflib_InvocationOnMock invocation) {
            authenticated = true;
            return null;
        }
    }

    private class InvoiceAnswer implements fflib_Answer {
        private final String invoiceNumber;
        public InvoiceAnswer(String invoiceNumber) {
            this.invoiceNumber = invoiceNumber;
        }
        public Object answer(fflib_InvocationOnMock invocation) {
            System.assert(
                authenticated,
                'authenticate() must be called before any createInvoice()'
            );
            return invoiceNumber;
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Id newAccountId() {
        return fflib_IDGenerator.generate(Account.SObjectType);
    }

    private static Id newOppId() {
        return fflib_IDGenerator.generate(Opportunity.SObjectType);
    }

    private static Opportunity makeOpp(Id id, Id accountId, String stage, Decimal amount) {
        return new Opportunity(
            Id = id,
            AccountId = accountId,
            StageName = stage,
            Amount = amount
        );
    }

    // ---------------------------------------------------------------------
    // authenticate() failure => InvoicingException, nothing happens
    // ---------------------------------------------------------------------

    @IsTest
    static void authenticationFailureThrowsAndDoesNothing() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IBillingGateway gateway =
            (IBillingGateway) mocks.mock(IBillingGateway.class);
        IOpportunitiesSelector selector =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uow =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        // Stubbing
        mocks.startStubbing();
        ((IBillingGateway) mocks.doThrowWhen(
            new BillingException('auth is down'), gateway)).authenticate();
        mocks.when(selector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Service.setMock(IBillingGateway.class, gateway);
        Application.Selector.setMock(selector);
        Application.UnitOfWork.setMock(uow);

        Set<Id> ids = new Set<Id>{ newOppId() };

        Boolean thrown = false;
        Test.startTest();
        try {
            InvoicingService.invoiceWonOpportunities(ids);
        } catch (InvoicingService.InvoicingException e) {
            thrown = true;
            System.assert(
                e.getMessage().contains('auth is down'),
                'Message should contain the gateway message: ' + e.getMessage()
            );
        }
        Test.stopTest();

        System.assert(thrown, 'Expected an InvoicingService.InvoicingException');

        // authenticate was attempted...
        ((IBillingGateway) mocks.verify(gateway, 1)).authenticate();
        // ...but nothing was invoiced, registered or committed.
        ((IBillingGateway) mocks.verify(gateway, 0)).createInvoice(
            fflib_Match.anyId(), fflib_Match.anyDecimal());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(
            fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).commitWork();
    }

    // ---------------------------------------------------------------------
    // Full invoicing logic
    // ---------------------------------------------------------------------

    @IsTest
    static void invoicesEligibleOpportunitiesAndHandlesFailures() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IBillingGateway gateway =
            (IBillingGateway) mocks.mock(IBillingGateway.class);
        IOpportunitiesSelector selector =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uow =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        // Build the data set.
        Id acc1 = newAccountId();
        Id acc2 = newAccountId();
        Id acc3 = newAccountId();
        Id acc4 = newAccountId();
        Id acc5 = newAccountId();
        Id acc6 = newAccountId();

        Decimal amt1 = 100;
        Decimal amt5 = 200;
        Decimal amt6 = 300;

        Opportunity opp1 = makeOpp(newOppId(), acc1, 'Closed Won', amt1);   // invoiced
        Opportunity opp2 = makeOpp(newOppId(), acc2, 'Closed Won', 0);      // skipped (amount 0)
        Opportunity opp3 = makeOpp(newOppId(), acc3, 'Prospecting', 500);   // skipped (not won)
        Opportunity opp4 = makeOpp(newOppId(), acc4, 'Closed Won', null);   // skipped (null amount)
        Opportunity opp5 = makeOpp(newOppId(), acc5, 'Closed Won', amt5);   // billing fails
        Opportunity opp6 = makeOpp(newOppId(), acc6, 'Closed Won', amt6);   // invoiced

        List<Opportunity> allOpps = new List<Opportunity>{
            opp1, opp2, opp3, opp4, opp5, opp6
        };
        Set<Id> ids = new Map<Id, Opportunity>(allOpps).keySet();

        // Stubbing
        mocks.startStubbing();
        // authenticate() (void) flips the flag the invoice answers assert on.
        ((IBillingGateway) mocks.doAnswer(new AuthAnswer(), gateway)).authenticate();
        mocks.when(selector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selector.selectById(ids)).thenReturn(allOpps);
        // Successful invoices assert ordering, then return a number.
        mocks.when(gateway.createInvoice(acc1, amt1)).thenAnswer(new InvoiceAnswer('INV-1001'));
        mocks.when(gateway.createInvoice(acc6, amt6)).thenAnswer(new InvoiceAnswer('INV-1006'));
        // One opportunity fails at the gateway.
        mocks.when(gateway.createInvoice(acc5, amt5))
            .thenThrow(new BillingException('card declined'));
        mocks.stopStubbing();

        Application.Service.setMock(IBillingGateway.class, gateway);
        Application.Selector.setMock(selector);
        Application.UnitOfWork.setMock(uow);

        Integer result;
        Test.startTest();
        result = InvoicingService.invoiceWonOpportunities(ids);
        Test.stopTest();

        // Returns count of successfully invoiced opportunities.
        System.assertEquals(2, result, 'Two opportunities should be invoiced');

        // Successful invoices set NextStep.
        System.assertEquals('Invoiced: INV-1001', opp1.NextStep);
        System.assertEquals('Invoiced: INV-1006', opp6.NextStep);

        // Failed invoice sets NextStep + Description.
        System.assertEquals('Billing failed', opp5.NextStep);
        System.assertEquals('card declined', opp5.Description);

        // Skipped opportunities untouched.
        System.assertEquals(null, opp2.NextStep);
        System.assertEquals(null, opp3.NextStep);
        System.assertEquals(null, opp4.NextStep);

        // authenticate called exactly once (ordering is enforced by InvoiceAnswer).
        ((IBillingGateway) mocks.verify(gateway, 1)).authenticate();

        // createInvoice called only for eligible opps, with the right args.
        ((IBillingGateway) mocks.verify(gateway, 3)).createInvoice(
            fflib_Match.anyId(), fflib_Match.anyDecimal());
        ((IBillingGateway) mocks.verify(gateway, 1)).createInvoice(acc1, amt1);
        ((IBillingGateway) mocks.verify(gateway, 1)).createInvoice(acc5, amt5);
        ((IBillingGateway) mocks.verify(gateway, 1)).createInvoice(acc6, amt6);

        // Every processed (invoiced or failed) opp is registered dirty.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 3)).registerDirty(
            fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).registerDirty(opp1);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).registerDirty(opp5);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).registerDirty(opp6);

        // Skipped opps never registered.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(opp2);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(opp3);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(opp4);

        // Committed exactly once.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).commitWork();
    }
}
