public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    /**
     * Validation on insert.
     */
    public override void onValidate() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            validateAmountNotNegative(opp);
        }
    }

    /**
     * Validation on update.
     */
    public override void onValidate(Map<Id, SObject> existingRecords) {
        for (Opportunity opp : (List<Opportunity>) Records) {
            // Rule 1: Amount must not be negative.
            validateAmountNotNegative(opp);

            // Rule 2: Amount cannot change when the opportunity was already Closed Won.
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp != null
                && oldOpp.StageName == 'Closed Won'
                && opp.Amount != oldOpp.Amount) {
                addAmountError('Amount cannot change on a won opportunity.', opp);
            }
        }
    }

    private void validateAmountNotNegative(Opportunity opp) {
        if (opp.Amount != null && opp.Amount < 0) {
            addAmountError('Amount cannot be negative.', opp);
        }
    }

    /**
     * Records the error through the fflib domain helper (so it is captured in
     * fflib_SObjectDomain.Errors for unit tests) AND flags the specific record's
     * Amount field so that only the offending record fails to save.
     */
    private void addAmountError(String message, Opportunity opp) {
        // Record it in fflib_SObjectDomain.Errors for unit tests.
        error(message, opp, Opportunity.Amount);
        // Fail the DML for this record only, on the Amount field.
        opp.Amount.addError(message);
    }

    /**
     * Standard fflib constructor inner class.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
