public with sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {

    // Stay well under the hard limit of 50 System.enqueueJob calls per transaction.
    private static final Integer MAX_JOBS = 45;

    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    /**
     * Enqueues one or more CaseSurveyJob instances for the given cases.
     *
     * A single list-view or API operation can close up to 200 cases at once, but Apex
     * allows at most 50 jobs to be enqueued per transaction. We therefore chunk the
     * cases into at most MAX_JOBS jobs. Each job runs in its own transaction, so a hard
     * failure in one job cannot roll back or affect the others.
     */
    public static void enqueueFor(List<Id> caseIds) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Ceiling division: never create more than MAX_JOBS jobs.
        Integer chunkSize = (caseIds.size() + MAX_JOBS - 1) / MAX_JOBS;

        for (Integer i = 0; i < caseIds.size(); i += chunkSize) {
            Integer endIndex = Math.min(i + chunkSize, caseIds.size());

            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < endIndex; j++) {
                chunk.add(caseIds[j]);
            }

            System.enqueueJob(new CaseSurveyJob(chunk));
        }
    }

    public void execute(QueueableContext context) {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
            AND ContactId != null
        ];

        Date dueDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();

        for (Case c : cases) {
            try {
                tasks.add(new Task(
                    WhatId       = c.Id,
                    WhoId        = c.ContactId,
                    Subject      = 'CSAT survey: ' + c.CaseNumber,
                    ActivityDate = dueDate,
                    Status       = 'Not Started'
                ));

                // Future vendor integration callout goes here, per case, so one
                // failing callout is isolated from the other cases in this job.
            } catch (Exception e) {
                // Isolate per-case failures; one bad case must not stop the rest.
                System.debug(LoggingLevel.ERROR,
                    'CSAT survey build failed for case ' + c.Id + ': ' + e.getMessage());
            }
        }

        if (!tasks.isEmpty()) {
            // Partial-success DML: a single task that fails to insert won't block the others.
            Database.SaveResult[] results = Database.insert(tasks, false);
            for (Database.SaveResult sr : results) {
                if (!sr.isSuccess()) {
                    System.debug(LoggingLevel.ERROR,
                        'CSAT survey task insert failed: ' + sr.getErrors());
                }
            }
        }
    }
}
