public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Single, bulk-safe query for everything we need.
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        if (opps.isEmpty()) {
            return 0;
        }

        // Build one message per opportunity, each targeting its own owner.
        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opps) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();

            // Emailing a User by Id (not saved as an activity) does not consume
            // the org's daily external single-email allocation.
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);

            String closeDateText = (opp.CloseDate == null)
                ? 'an unspecified date'
                : opp.CloseDate.format();

            email.setPlainTextBody(
                'The opportunity "' + opp.Name + '" is due for renewal on '
                + closeDateText + '. Please reach out to the customer to arrange the renewal.'
            );

            messages.add(email);
        }

        Integer sent = 0;

        // ONE sendEmail call for the whole batch, with allOrNone = false so a
        // single bad recipient does not roll back the rest. This is both
        // bulk-safe (Apex allows only 10 sendEmail invocations per transaction)
        // and still delivers partial success via per-message results.
        Messaging.SendEmailResult[] results = Messaging.sendEmail(messages, false);

        if (results != null) {
            for (Messaging.SendEmailResult result : results) {
                if (result.isSuccess()) {
                    sent++;
                }
            }
        }

        return sent;
    }
}
