/**
 * Routes one-off website gifts through NPSP's Batch Data Import (BDI) engine so that
 * NPSP's own contact matching, household creation and donation processing rules apply,
 * instead of inserting Contacts/Opportunities directly (which was creating duplicate donors).
 *
 * One npsp__DataImport__c record is staged per gift and left in the org as an audit trail.
 * Processing is synchronous and happens in the same transaction via NPSP's public Apex API.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    // NPSP stores the success status as this value on npsp__Status__c.
    private static final String STATUS_IMPORTED = 'Imported';

    /**
     * Stages one NPSP Data Import record per gift, processes them synchronously through
     * NPSP's BDI engine, and returns one ImportResult per gift in input order.
     *
     * @param gifts the website gifts to import (null/empty returns an empty list)
     * @return one ImportResult per input gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one NPSP Data Import record per gift, preserving input order.
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            dataImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                // The donor for these website gifts is an individual Contact.
                npsp__Donation_Donor__c          = 'Contact1'
            ));
        }

        // 2. Persist the staged rows so they remain in the org as the audit trail.
        insert dataImports;

        // 3. Use the org's configured Data Import settings via NPSP's API. This applies
        //    NPSP's defaults (match contacts on first name, last name and email; never
        //    match existing donations) and, crucially, guarantees a populated contact
        //    matching rule so existing donors are matched instead of duplicated.
        npsp__Data_Import_Settings__c diSettings =
            npsp.BDI_DataImport_API.getDefaultDataImportSettings();

        // 4. Process synchronously, in this same transaction, via NPSP's BDI Apex API.
        //    isDryRun = false -> perform the real import. NPSP writes its results back
        //    onto each npsp__DataImport__c record and isolates per-row failures.
        npsp.BDI_DataImport_API.processDataImportRecords(diSettings, dataImports, false);

        // 5. Re-query the processed rows to read back NPSP's results.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImports
        ]);

        // 6. Build one result per gift, in input order (dataImports mirrors gifts order).
        for (npsp__DataImport__c staged : dataImports) {
            npsp__DataImport__c processed = processedById.get(staged.Id);
            ImportResult result = new ImportResult();

            if (processed != null && processed.npsp__Status__c == STATUS_IMPORTED) {
                result.success = true;
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
            } else {
                result.success = false;
                result.errorMessage = (processed != null && processed.npsp__FailureInformation__c != null)
                    ? processed.npsp__FailureInformation__c
                    : 'NPSP did not import this gift.';
            }

            results.add(result);
        }

        return results;
    }
}
