public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objDescribe = FB_Employee__c.SObjectType.getDescribe();

        // If the running user cannot read the object at all, return an empty list.
        if (!objDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // Always-selectable base fields.
        List<String> selectFields = new List<String>{ 'Id', 'Name' };

        // Only include the custom fields the running user can actually read,
        // otherwise querying them throws "No such column".
        for (String fieldName : new List<String>{ 'Department__c', 'Salary__c', 'Personal_Email__c' }) {
            Schema.SObjectField field = fieldMap.get(fieldName);
            if (field != null && field.getDescribe().isAccessible()) {
                selectFields.add(fieldName);
            }
        }

        String query =
            'SELECT ' + String.join(selectFields, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        // Runs "with sharing", so only records shared to the running user are returned.
        List<FB_Employee__c> records = Database.query(query);

        // Extra safety: strip any inaccessible fields (removes them entirely,
        // does not throw when some fields are not readable).
        SObjectAccessDecision decision =
            Security.stripInaccessible(AccessType.READABLE, records);

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
