/**
 * Trigger Action (TAF) that prevents two Contacts on the same Account from
 * sharing an Email address (compared case-insensitively).
 *
 * Contacts without an Account or without an Email are not checked.
 * On update, only Contacts whose Email or AccountId changed are evaluated,
 * and a Contact never conflicts with itself.
 *
 * Bulk-safe: performs at most one SOQL query per trigger execution.
 */
public with sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void validate(List<Contact> newList, List<Contact> oldList) {
        // Build the old-values map on update so we can detect relevant changes.
        Map<Id, Contact> oldMap = null;
        if (oldList != null) {
            oldMap = new Map<Id, Contact>();
            for (Contact c : oldList) {
                oldMap.put(c.Id, c);
            }
        }

        // Determine which records actually need checking.
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            if (oldMap != null) {
                Contact prior = oldMap.get(c.Id);
                Boolean emailChanged = prior.Email != c.Email;
                Boolean accountChanged = prior.AccountId != c.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue; // unrelated edit - leave legacy duplicates alone
                }
            }
            toCheck.add(c);
            accountIds.add(c.AccountId);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // Single SOQL query: existing contacts on the relevant accounts.
        Map<String, Set<Id>> dbKeyToIds = new Map<String, Set<Id>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            String key = makeKey(existing.AccountId, existing.Email);
            Set<Id> ids = dbKeyToIds.get(key);
            if (ids == null) {
                ids = new Set<Id>();
                dbKeyToIds.put(key, ids);
            }
            ids.add(existing.Id);
        }

        // Evaluate each candidate in list order so the first one wins.
        Set<String> seenKeys = new Set<String>();
        for (Contact c : toCheck) {
            String key = makeKey(c.AccountId, c.Email);
            Boolean conflict = false;

            // Conflict with an existing database record (excluding self).
            Set<Id> ids = dbKeyToIds.get(key);
            if (ids != null) {
                for (Id existingId : ids) {
                    if (existingId != c.Id) {
                        conflict = true;
                        break;
                    }
                }
            }

            // Conflict with an earlier record in this same save.
            if (!conflict && seenKeys.contains(key)) {
                conflict = true;
            }

            if (conflict) {
                c.addError(ERROR_MESSAGE);
            } else {
                seenKeys.add(key);
            }
        }
    }

    private String makeKey(Id accountId, String email) {
        return accountId + '|' + email.toLowerCase();
    }
}
