/**
 * Trigger Action (TAF) that keeps Account.FB_Open_Case_Count__c equal to the number of
 * the account's Cases with IsClosed = false.
 *
 * Registered for after insert / update / delete / undelete on Case. In every one of those
 * contexts the database already reflects the final state of the Case rows, so a single
 * aggregate recalculation of the affected accounts is correct for all operations
 * (create, close, reopen, reparent, delete, undelete).
 *
 * Bulk-safe: at most one SOQL query and one DML statement per invocation.
 */
public with sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert,
               TriggerAction.AfterUpdate,
               TriggerAction.AfterDelete,
               TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        Map<Id, Case> oldMap = new Map<Id, Case>((List<Case>) triggerOld);
        for (Case c : (List<Case>) triggerNew) {
            Case oldCase = oldMap.get(c.Id);
            if (c.AccountId != oldCase.AccountId) {
                // Case was reparented: both the old and the new account may change.
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            } else if (c.IsClosed != oldCase.IsClosed && c.AccountId != null) {
                // Case was closed or reopened on the same account.
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerOld) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    /**
     * Recomputes the open case count for the given accounts and writes it back.
     * Accounts with no remaining open cases are set to 0 (never left blank).
     */
    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Seed every affected account with 0 so that accounts whose last open case
        // disappeared are updated to 0 rather than left unchanged.
        Map<Id, Integer> accountIdToCount = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            accountIdToCount.put(accountId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            accountIdToCount.put((Id) ar.get('accId'), (Integer) ar.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIdToCount.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = accountIdToCount.get(accountId)
            ));
        }

        update accountsToUpdate;
    }
}
