public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    // Static set persists for the whole transaction. When the RoundAmount action
    // (Order 20) re-updates the same Opportunities, this after-update action runs a
    // second time; recording the Ids we have already logged ensures we create at most
    // one "Amount changed" Task per Opportunity per transaction.
    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : triggerNew) {
            Opportunity oldOpp = oldById.get(opp.Id);

            // Only when Amount actually changed (null-safe Decimal comparison).
            if (opp.Amount == oldOpp.Amount) {
                continue;
            }

            // Skip if this Opportunity was already logged earlier in the transaction
            // (e.g. the rounding re-update firing this action a second time).
            if (loggedOpportunityIds.contains(opp.Id)) {
                continue;
            }

            loggedOpportunityIds.add(opp.Id);
            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId = opp.Id,
                Status = 'Completed'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
